// Original decoded MenusGraphics_droid atlas measurements and bitmap fills.
// Same correction as engine-ui/authored_hud_portrait_v4.cpp, align_v5:
// alpha>=128 connected paint bounding-box centres, not bitmap shape centres.
// Frame155 dark aperture atlas bounds[698,734]x[480,517], fill20/-15450/-9986.
const std::array<float,2> portrait_paint_centres[]{
 {700.f*15.10906982421875f-10293.f,687.f*15.10906982421875f-10052.f},
 {630.5f*15.10906982421875f-9234.f,688.5f*15.10906982421875f-10082.f},
 {559.f*15.10906982421875f-8160.f,689.f*15.10906982421875f-10082.f}
};
std::array<float,2> source_point(const Matrix& m,float x,float y){
 return {(m[0]*x+m[2]*y+m[4])/20.f,(m[1]*x+m[3]*y+m[5])/20.f};
}
std::array<float,2> portrait_aperture_centre(unsigned style){
 return source_point(static_layers[style][3].matrix,716.f*20.f-15450.f,498.5f*20.f-9986.f);
}
